<script setup lang="ts">
import {draftDataSchema,type DraftData,type Product} from '@ellas/shared';
interface DraftRecord{_id:string;data:DraftData;version:number;analysis:string;duplicates?:{_id:string;number:string}[];requestId?:string}
definePageMeta({layout:'admin',middleware:'staff'});useSeo('Asistente del equipo','Borradores privados y gestión asistida de solicitudes.');
const {staff,mutate}=useStaff();const mode=ref<'capture'|'chat'>('capture');const channel=ref<'whatsapp'|'instagram'|'email'|'otro'>('whatsapp');const text=ref('');const file=ref<File|null>(null);const captureInput=ref<HTMLInputElement>();
function clearCapture(){file.value=null;if(captureInput.value)captureInput.value.value='';}
const consent=ref(false);const busy=ref(false);const failure=ref('');const draft=ref<DraftRecord|null>(null);const action=ref<{id:string;token:string;summary:string;expiresAt:string;kind:string}|null>(null);const chosen=ref<Product|null>(null);const configurator=ref<{clearAdded:()=>void}>();const saved=ref('');const savedData=ref('');const dirty=computed(()=>Boolean(draft.value&&!draft.value.requestId&&JSON.stringify(draft.value.data)!==savedData.value));
const {data:listing,refresh:refreshListing}=await useFetch<{drafts:{_id:string;data:{channel:string;contact:{name:string}};requestId?:string;updatedAt:string}[]}>('/api/admin/assistant/drafts');
async function load(id:string){if(dirty.value){failure.value='Guarda o descarta las ediciones actuales antes de abrir otro borrador.';return;}failure.value='';try{draft.value=await $fetch<DraftRecord>(`/api/admin/assistant/drafts/${id}`);savedData.value=JSON.stringify(draft.value.data);action.value=null;chosen.value=null;}catch(e){failure.value=errorMessage(e);}}
async function analyze(){if(busy.value)return;busy.value=true;failure.value='';action.value=null;try{const body=new FormData();body.append('channel',channel.value);body.append('text',text.value);body.append('consent','true');if(file.value)body.append('capture',file.value);const result=await mutate<{_id:string}>('/api/admin/assistant/drafts/analyze',{method:'POST',body});await load(result._id);await refreshListing();clearCapture();}catch(e){failure.value=errorMessage(e);}finally{busy.value=false;}}
async function manual(){failure.value='';const data=draftDataSchema.parse({channel:channel.value,type:'presupuesto',externalId:'',contact:{name:'',company:'',email:'',phone:''},lines:[],personalization:{enabled:false,technique:'asesoramiento',placement:'',notes:''},notes:'',desiredDate:'',unresolved:[],captureNote:'',notify:false,duplicateReviewed:false});try{const result=await mutate<{_id:string}>('/api/admin/assistant/drafts',{method:'POST',body:data});await load(result._id);await refreshListing();}catch(e){failure.value=errorMessage(e);}}
function attach(event:Event){const selected=(event.target as HTMLInputElement).files?.[0];if(selected&&selected.size>3*1024*1024){failure.value='La captura supera los 3 MB';return;}file.value=selected||null;}
function add(lines:{reference:string;color:string;size:string;quantity:number}[]){if(!draft.value)return;for(const line of lines){const existing=draft.value.data.lines.find(l=>l.reference===line.reference&&l.color===line.color&&l.size===line.size);if(existing)existing.quantity+=line.quantity;else draft.value.data.lines.push({reference:line.reference,color:line.color,size:line.size,quantity:line.quantity});}configurator.value?.clearAdded();action.value=null;}
async function save(){if(!draft.value)return false;failure.value='';saved.value='';try{const result=await mutate<DraftRecord>(`/api/admin/assistant/drafts/${draft.value._id}`,{method:'PUT',body:{data:draft.value.data,version:draft.value.version}});draft.value=result;savedData.value=JSON.stringify(result.data);action.value=null;saved.value='Borrador guardado.';await refreshListing();return true;}catch(e){failure.value=errorMessage(e);return false;}}
async function review(){if(busy.value)return;busy.value=true;try{if(!await save()||!draft.value)return;action.value=await mutate(`/api/admin/assistant/drafts/${draft.value._id}/review`,{method:'POST',body:{version:draft.value.version}});}catch(e){failure.value=errorMessage(e);}finally{busy.value=false;}}
watch(()=>draft.value?.data,()=>{action.value=null;saved.value='';},{deep:true,flush:'sync'});
</script>
<template><div v-if="staff?.role!=='admin'" class="empty-state"><h1>Acceso de administrador</h1><p>El asistente de gestión requiere una cuenta de administrador.</p></div><template v-else><div class="admin-title"><div><span class="eyebrow">UNA CONVERSACIÓN. UN PEDIDO BIEN PREPARADO.</span><h1>Asistente del equipo</h1><p>Del mensaje recibido a una solicitud que puedes revisar y gestionar.</p></div><NuxtLink to="/admin/solicitudes" class="button outline">Ver solicitudes <AppIcon name="ArrowRight" :size="16"/></NuxtLink></div><div class="assistant-mode-tabs"><button :class="{active:mode==='capture'}" @click="mode='capture'">Entrada de otros canales</button><button :class="{active:mode==='chat'}" @click="mode='chat'">Consultar y gestionar</button></div><AssistantPanel v-if="mode==='chat'" admin inline/><div v-else class="admin-capture-layout"><div><section class="admin-card capture-card"><h2>¿Qué te han pedido?</h2><p class="fine-print">Pega solo el contenido necesario. Puedes retirar datos ajenos al pedido antes de enviarlo a OpenAI.</p><label>Canal de origen<select v-model="channel"><option value="whatsapp">WhatsApp</option><option value="instagram">Instagram</option><option value="email">Correo</option><option value="otro">Otro canal</option></select></label><label>Mensaje recibido<textarea v-model="text" rows="6" maxlength="12000" placeholder="Ej. Necesito 10 polos negros: 4 M y 6 L, con logo en pecho…"/></label><label>Captura opcional · PNG, JPG o WebP, hasta 3 MB<input ref="captureInput" type="file" accept="image/png,image/jpeg,image/webp" @change="attach"/></label><p v-if="file" class="fine-print">Seleccionada: {{file.name}}. Se analiza en memoria; la imagen no se conserva. <button type="button" class="text-link" @click="clearCapture">Quitar captura</button></p><label class="checkbox-row"><input v-model="consent" type="checkbox"/><span>He revisado el contenido y autorizo su análisis con OpenAI para preparar este borrador.</span></label><button class="button dark" :disabled="busy||dirty||!consent||(!text.trim()&&!file)" @click="analyze">{{busy?'Interpretando el mensaje…':'Preparar borrador con IA'}} <AppIcon name="ArrowUpRight" :size="18"/></button><button class="text-link manual-draft" :disabled="busy||dirty" @click="manual">Crear borrador manualmente <AppIcon name="Plus" :size="16"/></button></section><div v-if="dirty" class="alert"><div><b>Tienes ediciones sin guardar.</b><p>Guárdalas antes de abrir otro mensaje.</p><button class="text-link" @click="save">Guardar cambios <AppIcon name="Check" :size="14"/></button><button class="text-link" style="margin-left:20px" @click="draft!.data=draftDataSchema.parse(JSON.parse(savedData))">Descartar ediciones</button></div></div><p v-if="failure" class="alert error" role="alert">{{failure}}</p><section v-if="draft" class="admin-card draft-editor"><div class="section-heading small"><h2>Revisa el borrador</h2><span class="badge">{{draft.data.channel}}</span></div><NuxtLink v-if="draft.requestId" :to="`/admin/solicitudes/${draft.requestId}`" class="button lime">Abrir solicitud registrada <AppIcon name="ArrowRight"/></NuxtLink><template v-else><p class="fine-print">Lo que no constaba en el mensaje sigue vacío. No se ha creado ni confirmado ningún pedido.</p><details v-if="draft.analysis" class="draft-evidence"><summary>Ver lo que se ha leído</summary><p class="preserve-lines">{{draft.analysis}}</p></details><div v-if="draft.data.unresolved.length" class="draft-unresolved"><h3>Antes de continuar</h3><p class="fine-print">Completa las prendas y retira cada duda solo cuando la hayas resuelto o descartado expresamente.</p><div v-for="(issue,i) in draft.data.unresolved" :key="i"><p>{{issue}}</p><button class="text-link" @click="draft.data.unresolved.splice(i,1)">Resuelto o descartado <AppIcon name="Check" :size="14"/></button></div></div><label>Canal de este borrador<select v-model="draft.data.channel"><option value="whatsapp">WhatsApp</option><option value="instagram">Instagram</option><option value="email">Correo</option><option value="otro">Otro canal</option></select></label><div class="form-grid"><label>Nombre<input v-model="draft.data.contact.name" maxlength="100"/></label><label>Empresa<input v-model="draft.data.contact.company" maxlength="150"/></label><label>Email<input v-model="draft.data.contact.email" type="email" maxlength="254"/></label><label>Teléfono<input v-model="draft.data.contact.phone" type="tel" maxlength="30"/></label><label>Referencia del mensaje externo · opcional<input v-model="draft.data.externalId" maxlength="150"/></label><label>Tipo de solicitud<select v-model="draft.data.type"><option value="presupuesto">Presupuesto</option><option value="pedido">Pedido pendiente de confirmación</option></select></label></div><h3>Prendas interpretadas</h3><div v-if="draft.data.lines.length" class="table-scroll"><table class="admin-table"><thead><tr><th>Referencia</th><th>Color</th><th>Talla</th><th>Uds.</th><th/></tr></thead><tbody><tr v-for="(line,i) in draft.data.lines" :key="i"><td>{{line.reference}}</td><td>{{line.color}}</td><td>{{line.size}}</td><td><input v-model.number="line.quantity" type="number" min="1" max="10000" step="1" :aria-label="`Cantidad línea ${i+1}`"/></td><td><button class="icon-button" :aria-label="`Quitar línea ${i+1}`" @click="draft.data.lines.splice(i,1)"><AppIcon name="X" :size="15"/></button></td></tr></tbody></table></div><p v-else class="fine-print">Aún no hay variantes identificadas. Añádelas debajo.</p><ProductSearch id="draft-product-search" label="Añadir o corregir una prenda" @select="chosen=$event"/><VariantConfigurator v-if="chosen" ref="configurator" :persist="false" :product="chosen" @add="add"/><label class="checkbox-row"><input v-model="draft.data.personalization.enabled" type="checkbox"/>Personalización solicitada</label><label>Técnica solicitada<select v-model="draft.data.personalization.technique"><option value="asesoramiento">Necesito asesoramiento</option><option value="bordado">Bordado</option><option value="serigrafia">Serigrafía</option><option value="dtf">DTF</option><option value="transfer">Transfer</option></select></label><label>Ubicación del logo<input v-model="draft.data.personalization.placement" maxlength="200"/></label><label>Detalles de personalización<textarea v-model="draft.data.personalization.notes" rows="2" maxlength="2000"/></label><label>Observaciones<textarea v-model="draft.data.notes" rows="2" maxlength="3000"/></label><label>Fecha deseada<input v-model="draft.data.desiredDate" type="date"/></label><label>Cómo se obtuvieron los datos de contacto<textarea v-model="draft.data.captureNote" rows="2" maxlength="1000" placeholder="Ej. datos facilitados por el cliente al solicitar presupuesto por WhatsApp. No marques consentimiento web en su nombre."/></label><label class="checkbox-row"><input v-model="draft.data.notify" type="checkbox"/><span>Enviar avisos por email al crear la solicitud. En demo, ambos se redirigen a ugasdomingo@gmail.com. No se envían al guardar este borrador.</span></label><div v-if="draft.duplicates?.length" class="alert"><div><b>Posibles coincidencias con solicitudes existentes</b><p v-for="match in draft.duplicates" :key="match._id"><NuxtLink :to="`/admin/solicitudes/${match._id}`" target="_blank">{{match.number}}</NuxtLink></p><p class="fine-print">Comprueba que se trata de otra solicitud antes de crearla. No se fusionan automáticamente.</p><label class="checkbox-row"><input v-model="draft.data.duplicateReviewed" type="checkbox"/>He revisado las coincidencias: es otra solicitud.</label></div></div><p v-if="saved" role="status" class="alert success">{{saved}}</p><div class="draft-footer"><button class="button outline" :disabled="busy" @click="save">Guardar borrador</button><button class="button dark" :disabled="busy" @click="review">Revisar para crear solicitud <AppIcon name="ArrowRight" :size="17"/></button></div><ActionReview v-if="action" :action="action" @done="draft.requestId=$event.id;refreshListing()"/></template></section></div><aside class="admin-card saved-drafts"><h2>Borradores guardados</h2><p class="fine-print">Privados de tu cuenta. Caducan a los 30 días.</p><button v-for="item in listing?.drafts" :key="item._id" class="saved-draft" :disabled="dirty" @click="load(item._id)"><b>{{item.data.contact.name||'Sin nombre todavía'}}</b><span>{{item.data.channel}} · {{item.requestId?'Solicitud registrada':'Pendiente de revisión'}}</span><small>{{new Date(item.updatedAt).toLocaleDateString('es-ES')}}</small></button><p v-if="!listing?.drafts.length" class="fine-print">Todavía no tienes borradores.</p></aside></div></template></template>
